def convert_currency_list(strings):
    return [process(s) for s in strings]

def process(s):
    s = s.strip()
    if not s:
        return None
    if s[0] == '(' and s[-1] == ')':
        inner = s[1:-1]
        inner_value = process(inner)
        if inner_value is None:
            return None
        else:
            return -inner_value
    else:
        clean_str = s.replace(',', '')
        try:
            return float(clean_str)
        except ValueError:
            return None
