class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

def split(head):
    if head is None or head.next is None:
        return head, None
    slow = head
    fast = head.next
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    second_head = slow.next
    slow.next = None
    if second_head:
        second_head.prev = None
    return head, second_head

def merge(a, b):
    if not a:
        return b
    if not b:
        return a
    merged_head = None
    merged_tail = None
    while a and b:
        if a.data <= b.data:
            next_node = a
            a = a.next
        else:
            next_node = b
            b = b.next
        next_node.next = None
        if not merged_head:
            merged_head = next_node
            merged_tail = next_node
            merged_head.prev = None
        else:
            merged_tail.next = next_node
            next_node.prev = merged_tail
            merged_tail = next_node
    remaining = a if a else b
    if remaining:
        if not merged_tail:
            merged_head = remaining
            merged_tail = remaining
            merged_head.prev = None
        else:
            remaining.prev = merged_tail
            merged_tail.next = remaining
        current = remaining
        while current.next:
            current = current.next
        merged_tail = current
    return merged_head

def merge_sort(head):
    if head is None or head.next is None:
        return head
    first, second = split(head)
    first_sorted = merge_sort(first)
    second_sorted = merge_sort(second)
    return merge(first_sorted, second_sorted)

def main():
    n = int(input().strip())
    if n == 0:
        print()
        return
    elements = list(map(int, input().split()))
    head = None
    last_node = None
    for num in elements:
        new_node = Node(num)
        if head is None:
            head = new_node
            last_node = head
        else:
            last_node.next = new_node
            new_node.prev = last_node
            last_node = new_node
    sorted_head = merge_sort(head)
    result = []
    current = sorted_head
    while current:
        result.append(str(current.data))
        current = current.next
    print(' <-> '.join(result))

if __name__ == "__main__":
    main()
