import heapq

def main():
    import math
    N, P, X, Y = map(int, input().split())
    edges = []
    for _ in range(P):
        a, b, c = map(int, input().split())
        edges.append((a, b, c))

    M = int(input())
    SW_nodes = list(map(int, input().split()))
    SW_nodes_set = set(SW_nodes)

    # Build SWERC's subgraph
    adj_swerc = [[] for _ in range(N + 1)]
    for a, b, c in edges:
        if a in SW_nodes_set and b in SW_nodes_set:
            adj_swerc[a].append((b, c))
            adj_swerc[b].append((a, c))

    INF = float('inf')

    def dijkstra_swerc():
        dist = [INF] * (N + 1)
        length = [INF] * (N + 1)
        heap = []
        dist[X] = 0
        length[X] = 0
        heapq.heappush(heap, (0, 0, X))
        while heap:
            cost, l, u = heapq.heappop(heap)
            if u == Y:
                return (cost, l)
            if cost > dist[u]:
                continue
            for (v, c) in adj_swerc[u]:
                new_cost = cost + c
                new_len = l + 1
                if new_cost < dist[v] or (new_cost == dist[v] and new_len < length[v]):
                    if new_cost < dist[v]:
                        dist[v] = new_cost
                        length[v] = new_len
                        heapq.heappush(heap, (new_cost, new_len, v))
                    else:
                        if length[v] > new_len:
                            length[v] = new_len
                            heapq.heappush(heap, (new_cost, new_len, v))
        return (INF, INF)

    C_swerc, L_swerc = dijkstra_swerc()
    if C_swerc == INF:
        print("Impossible")
        return

    # Compute all graph's minimal path
    adj_all = [[] for _ in range(N + 1)]
    for a, b, c in edges:
        adj_all[a].append((b, c))
        adj_all[b].append((a, c))

    def dijkstra_all():
        dist = [INF] * (N + 1)
        dist[X] = 0
        heap = [(0, X)]
        while heap:
            d, u = heapq.heappop(heap)
            if u == Y:
                return d
            if d > dist[u]:
                continue
            for (v, c) in adj_all[u]:
                new_d = d + c
                if new_d < dist[v]:
                    dist[v] = new_d
                    heapq.heappush(heap, (new_d, v))
        return INF

    C_all_min = dijkstra_all()
    if C_all_min < C_swerc:
        print("Impossible")
        return

    # Compute minimal cost for each length up to L_swerc-1
    max_len = L_swerc - 1
    if max_len < 0:
        print("Infinity")
        return

    prev = [INF] * (N + 1)
    prev[X] = 0
    min_costs = [INF] * (max_len + 2)  # 1-based up to max_len

    for l in range(1, max_len + 1):
        curr = [INF] * (N + 1)
        for u in range(N + 1):
            if prev[u] == INF:
                continue
            for (v, c) in adj_all[u]:
                if curr[v] > prev[u] + c:
                    curr[v] = prev[u] + c
        prev = curr.copy()
        min_costs[l] = prev[Y] if prev[Y] != INF else INF

    candidates = []
    for l in range(1, L_swerc):
        if min_costs[l] != INF and min_costs[l] >= C_swerc:
            numerator = min_costs[l] - C_swerc
            denominator = L_swerc - l
            val = numerator / denominator
            candidates.append(val)

    if not candidates:
        print("Infinity")
    else:
        min_val = min(candidates)
        if min_val < 1:
            print("Impossible")
        else:
            ans = int(math.floor(min_val))
            if ans <= 0:
                print("Impossible")
            else:
                print(ans)

if __name__ == "__main__":
    main()
```

