def main():
    import sys
    n = int(sys.stdin.readline())
    nodes = list(map(int, sys.stdin.readline().split()))
    target = int(sys.stdin.readline())

    # Build the BST
    root = None
    for val in nodes:
        if not root:
            root = Node(val)
        else:
            current = root
            while True:
                if val < current.val:
                    if current.left is None:
                        current.left = Node(val)
                        break
                    else:
                        current = current.left
                else:
                    if current.right is None:
                        current.right = Node(val)
                        break
                    else:
                        current = current.right

    # Find the closest value
    closest_val = root.val
    closest_diff = abs(closest_val - target)
    current_node = root

    while current_node is not None:
        current_val = current_node.val
        current_diff = abs(current_val - target)
        if (current_diff < closest_diff) or (current_diff == closest_diff and current_val < closest_val):
            closest_val = current_val
            closest_diff = current_diff

        if target < current_val:
            current_node = current_node.left
        else:
            current_node = current_node.right

    print(closest_val)

if __name__ == "__main__":
