import random
from collections import defaultdict

def adaptable_minimax(opponent_history, my_history, honest1, honest2):
    # Honest phase: decide declaration based on opponent's history
    if honest1 is None and honest2 is None:
        if not opponent_history:
            return random.choice(['R', 'P', 'S'])
        # Count opponent's declared moves
        counts = defaultdict(int)
        for decl, _ in opponent_history:
            counts[decl] += 1
        max_count = max(counts.values())
        modes = [move for move, cnt in counts.items() if cnt == max_count]
        most_common = random.choice(modes)
        # Choose a move that beats most_common
        if most_common == 'R':
            return 'P'
        elif most_common == 'P':
            return 'S'
        else:
            return 'R'
    else:
        # Real phase: chose move using minimax
        their_decl = honest1
        my_decl = honest2
        best_score = -float('inf')
        best_moves = []
        for my_move in ['R', 'P', 'S']:
            candidates = []
            for их_move in ['R', 'P', 'S']:
                их_b = 1 if их_move == их_decl else 0
                my_b = 1 if my_move == my_decl else 0
                # Determine outcome
                if my_move == их_move:
                    их_out, my_out = 1, 1
                else:
                    if (my_move == 'R' and их_move == 'S') or \
                       (my_move == 'P' and их_move == 'R') or \
                       (my_move == 'S' and их_move == 'P'):
                        my_out, их_out = 2, 0
                    else:
                        my_out, их_out = 0, 2
                их_total = их_b + их_out
                my_total = my_b + my_out
                candidates.append((их_total, my_total))
            # Calculate min my_total for max их_totals
            if not candidates:
                continue
            max_их = max(x[0] for x in candidates)
            min_my = min(x[1] for x in candidates if x[0] == max_их)
            if min_my > best_score:
                best_score = min_my
                best_moves = [my_move]
            elif min_my == best_score:
                best_moves.append(my_move)
        # Random selection among best moves
        return random.choice(best_moves)
