        if self.head.data == x:
            self.head = self.head.next
            if not self.head:
                self.tail = None
            return
        current = self.head
        while current and current.next:
            if current.next.data == x:
                if current.next == self.tail:
                    self.tail = current
                current.next = current.next.next
                return
            current = current.next

    def print_list(self):
        if not self.head:
            return
        current = self.head
        elements = []
        while current:
            elements.append(str(current.data))
            current = current.next
        print(' '.join(elements))

def main():
