def main():
    try:
        type_name = input().strip()
        if type_name not in ['list', 'tuple', 'set', 'dict']:
            raise ValueError("Invalid type provided")

        content_str = input().strip()
        predicate_str = input().strip()

        # Parse the object from the second input line
        obj = ast.literal_eval(content_str)

        # Check if object's type matches the specified type
        expected_type = {
            'list': list,
            'tuple': tuple,
            'set': set,
            'dict': dict
        }[type_name]
        if not isinstance(obj, expected_type):
            raise ValueError("Object type does not match specified type")

        # Parse the predicate function
        predicate_func = eval(predicate_str)
        if not callable(predicate_func):
            raise TypeError("Predicate is not a function")

        # Filter elements or entries based on predicate
        if type_name in ['list', 'tuple', 'set']:
            filtered = []
            for elem in obj:
                include = False
                try:
                    include = bool(predicate_func(elem))
                except:
                    pass  # Exclude element on error
                if include:
                    filtered.append(elem)
            # Convert to correct type
            if type_name == 'list':
                new_obj = filtered
            elif type_name == 'tuple':
                new_obj = tuple(filtered)
            else:  # 'set'
                new_obj = set(filtered)
        else:  # type is 'dict'
            new_obj = {}
            for key, value in obj.items():
                include = False
                try:
                    include = bool(predicate_func(value))
                except:
                    pass  # Exclude entry on error
                if include:
                    new_obj[key] = value
    except Exception:
        # Handle all exceptions by returning the empty form of the given type
        empty_types = {
            'list': [],
            'tuple': tuple(),
            'set': set(),
            'dict': {}
        }
        new_obj = empty_types.get(type_name, [])

    # Output using the type's __repr__ to maintain formatting
