class CustomDict:
    def __init__(self):
        self.data = []

    def __getitem__(self, key):
        if not isinstance(key, int):
            raise TypeError("Key must be an integer")
        if key < 0:
            raise KeyError("Key cannot be negative")
        if key >= len(self.data):
            return None
        return self.data[key]

    def __setitem__(self, key, value):
        if not isinstance(key, int):
            raise TypeError("Key must be an integer")
        if key < 0:
            raise KeyError("Key cannot be negative")
        desired_len = key + 1
        current_len = len(self.data)
        if current_len < desired_len:
            extension = [None] * (desired_len - current_len)
            self.data.extend(extension)
        self.data[key] = value

    def __contains__(self, key):
        if not isinstance(key, int):
            return False
        if key < 0:
            return False
        if key >= len(self.data):
            return False
        return self.data[key] is not None


def fib(n, memo):
    if n in memo:
        return memo[n]
    if n == 0:
        res = 0
    elif n == 1:
        res = 1
    else:
        res = fib(n - 1, memo) + fib(n - 2, memo)
    memo[n] = res
    return res


n = int(input())
memo = CustomDict()
print(fib(n, memo))
