from collections import deque

def main():
    n = int(sys.stdin.readline())
    adj = [[] for _ in range(n)]
    for i in range(n):
        parts = sys.stdin.readline().split()
        adj[i] = list(map(int, parts))

    color = [-1] * n
    for i in range(n):
        if color[i] == -1:
            if not bfs(i, adj, color):
                print('False')
                return
    print('True')

def bfs(start, adj, color):
    q = deque()
    color[start] = 0
    q.append(start)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if color[v] == -1:
                color[v] = 1 - color[u]
                q.append(v)
            elif color[v] == color[u]:
                return False
    return True

if __name__ == "__main__":
    main()
