    return { userId: payload.sub, username: payload.username };
  }
}
```

### 4. **Create Custom Decorator to Extract JWT**
```typescript
// decorators/jwt.decorator.ts
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const JwtToken = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    return request.headers.authorization?.split(' ')[1]; // Extract token from "Bearer <token>"
  },
);
```

### 5. **Protect Routes with Guard and Use Decorator**
```typescript
// example.controller.ts
import { Controller, Get, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { JwtToken } from './decorators/jwt.decorator';

@Controller('protected')
export class ProtectedController {
  @Get()
  @UseGuards(AuthGuard('jwt')) // Enforce JWT authentication
  getProtectedData(@JwtToken() token: string) {
    return {
      message: 'Access granted',
      token: token, // Token extracted from header
    };
  }
}
```

### 6. **Add Token to Requests (Client-Side)**
When calling protected routes, include the JWT in the `Authorization` header:
```javascript
// Example Axios request
axios.get('/protected', {
  headers: {
    Authorization: `Bearer YOUR_JWT_TOKEN_HERE`,
  },
});
```

### Key Points:
1. **Token Generation**: Use `AuthService` to sign tokens during login (not shown here).
2. **Security**: 
   - Store `YOUR_SECRET_KEY` in environment variables (e.g., `.env`).
   - Use `@UseGuards(AuthGuard('jwt'))` to protect endpoints.
3. **Decorator**: `@JwtToken()` extracts the raw JWT from the `Authorization` header for use in controllers.

### Testing Flow:
1. Get a JWT via login` endpoint (implement separately).
2. Call `/protected` with header: `Authorization: Bearer <token>`.
3. The decorator injects the token into the controller method.

This setup ensures secure authentication while providing direct access to the JWT token in protected routes via a clean decorator interface.

